#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> pesos(N);
    int soma = 0;

    for (int &peso : pesos) {
        cin >> peso;
        soma += peso;
